        script = " ".join(words[1:]) if base == "eval" else d._inline_script(words)
        if script is not None and (base == "eval" or base in d._C_SHELLS) and script.strip().startswith(("$", "`")):
            out.add("T2-computed-script")
        if d._heredoc_runs(words):
            for hs in d._herestrings(seg):
                if hs.strip().startswith(("$", "`")):
