def reflow(path):
    lines = open(path, encoding="utf-8").read().split("\n")
    changed = True
    while changed:
        changed = False
        for i, l in enumerate(lines):
            if len(l) > W and not l.lstrip().startswith("|"):
                end = block_end(lines, i)
                m = item.match(l)
                first_prefix = re.match(r"\s*", l).group()
                if m:
                    cont = " " * len(m.group())
                elif i + 1 < end:
                    cont = re.match(r"\s*", lines[i + 1]).group()
                else:
                    cont = first_prefix
                text = l[len(first_prefix):]
                words = (text + " " + " ".join(x.strip() for x in lines[i + 1:end])).split()
                out, cur, pre = [], "", first_prefix
                for w in words:
                    cand = (cur + " " + w) if cur else w
                    if len(pre) + len(cand) > W and cur:
                        out.append(pre + cur)
                        pre, cur = cont, w
                    else:
                        cur = cand
                out.append(pre + cur)
                lines[i:end] = out
                changed = True
                break
    open(path, "w", encoding="utf-8").write("\n".join(lines))
for p in sys.argv[1:]:
