hits = 0
for p in open(sys.argv[1]).read().split("\n"):
    if not p: continue
    try: t = open(p, encoding="utf-8", errors="replace").read()
    except OSError: continue
    names = {a or b for a, b in decl.findall(t)}
    names -= {"new"}
    if not names: continue
    pat = re.compile(r"(?<![\w$@%&>:.])(" + "|".join(map(re.escape, names)) + r")[ \t]+(/[^\s=/]|<<[A-Za-z_\"'~-])")
    for n, line in enumerate(t.split("\n"), 1):
        s = line.lstrip()
        if s.startswith("#"): continue
        m = pat.search(line)
        if m:
            hits += 1
            if hits <= 40: print(f"{p}:{n}: {line.strip()[:140]}")
print("hits", hits)
