# родителя с PID хука; хук умер — SIGKILL всей группе. Аргументы: PID хука, PATH-разрешённая команда claude.
WATCHDOG_POLL = 0.5
_WATCHDOG = f"""
import os, signal, subprocess, sys
hook = int(sys.argv[1])
try:
    proc = subprocess.Popen(sys.argv[2:])
except OSError:
    sys.exit(127)
while True:
    if os.getppid() != hook:
        os.killpg(0, signal.SIGKILL)
    try:
        sys.exit(proc.wait(timeout={WATCHDOG_POLL}))
    except subprocess.TimeoutExpired:
        pass
