    model — message.model последнего ответа ассистента основной ветки, кроме служебных моделей вида «<…>»;
    plan_file — последний attachment.planFilePath; turn_messages — непустые тексты ответов ассистента основной
    ветки после последней реплики автора, по порядку.
    """
    model: str = None
    plan_file: pathlib.Path = None
    turn_messages: list = dataclasses.field(default_factory=list)


def _texts(content, kind):
    """Тексты блоков type == kind списка content; строка content — один текст."""
    if isinstance(content, str):
        return [content]
    if not isinstance(content, list):
        return []
    return [b.get("text") for b in content
            if isinstance(b, dict) and b.get("type") == kind and isinstance(b.get("text"), str)]


def _is_author_turn(entry, msg):
    """Реплика автора: запись user основной ветки с текстом, без tool_result. Записи isMeta — служебные вставки
    Claude Code (тело навыка, оговорки команд), они приходят и посреди реплики."""
    if entry.get("isMeta"):
        return False
    content = msg.get("content")
    if isinstance(content, str):
        return True
    if not isinstance(content, list):
        return False
    kinds = {b.get("type") for b in content if isinstance(b, dict)}
    return "text" in kinds and "tool_result" not in kinds


def read_transcript(path):
    """Transcript из файла JSONL path; нет пути, файла или ошибка чтения — пустой Transcript.
    Строки не JSON и записи не словари пропускаются."""
    out = Transcript()
    if not isinstance(path, str) or not path:
        return out
    plan = None
    try:
        with open(path, encoding="utf-8", errors="replace") as f:
            for line in f:
                try:
                    entry = json.loads(line)
                except json.JSONDecodeError:
                    continue
                if not isinstance(entry, dict):
                    continue
                att = entry.get("attachment")
                p = att.get("planFilePath") if isinstance(att, dict) else None
                if isinstance(p, str) and p:
                    plan = p
                msg = entry.get("message")
                if entry.get("isSidechain") or not isinstance(msg, dict):
                    continue
                if entry.get("type") == "user" and _is_author_turn(entry, msg):
                    out.turn_messages = []
                elif entry.get("type") == "assistant":
                    model = msg.get("model")
                    # Служебные ответы помечены моделью вида «<synthetic>»: --model её не примет.
                    if isinstance(model, str) and model and not model.startswith("<"):
                        out.model = model
                    text = "".join(_texts(msg.get("content"), "text"))
                    if text.strip():
                        out.turn_messages.append(text)
    except (OSError, ValueError):
        return Transcript()
    out.plan_file = pathlib.Path(plan) if plan else None
    return out


