    except (OSError, ValueError, AttributeError):
        return None
    return value if isinstance(value, str) and value else None


def _inside(path, directory):
    return os.path.commonpath([path, directory]) == directory


def _in_memory_dir(path, projects):
    """Путь — под <projects>/<проект>/memory/; memory/, которая символьная ссылка, сравнивается и по цели
    ссылки."""
    if _inside(path, projects):
        parts = os.path.relpath(path, projects).split(os.sep)
        if len(parts) >= 3 and parts[1] == "memory":
            return True
    for memory in glob.glob(os.path.join(glob.escape(projects), "*", "memory")):
        if os.path.islink(memory):
            directory = os.path.realpath(memory)
            if _inside(path, directory) and path != directory:
                return True
    return False


def is_memory_path(path):
    """Путь в абсолютной нормализованной форме — как написан или разрешённый: файл автопамяти, CLAUDE.md
