    raw_config = os.path.abspath(os.path.expanduser(config_dir()))
    for config in _forms(raw_config):
        if path in _forms(os.path.join(config, "CLAUDE.md")):
            return True
        for rules in _forms(os.path.join(config, "rules")):
            if _inside(path, rules) and path != rules and path.endswith(".md"):
                return True
        if any(_in_memory_dir(path, projects) for projects in _forms(os.path.join(config, "projects"))):
            return True
    override = _auto_memory_override(raw_config)
    if override is not None and os.path.isabs(os.path.expanduser(override)):
        for directory in _forms(override):
            if _inside(path, directory) and path != directory:
                return True
    return False


