    обновление системы."""
    args = w[1:]
    letters, longs, skip = set(), set(), False
    for a in args:
        if skip:
            skip = False
        elif a == "--":
            break
        elif a.startswith("--"):
            longs.add(a.partition("=")[0])
            skip = a in _PACMAN_VALUE_FLAGS
        elif a.startswith("-") and len(a) > 1:
            letters.update(a[1:])
            skip = _takes_value(a, _PACMAN_VALUE_FLAGS)
